import { verifies } from "@halonicjs/testing-spec";
import { expect, test } from "vitest";
import {
  findVendoredProblems,
  type LicencePolicy,
  leadingComments,
  thirdPartyLicenceMark,
} from "./licences.ts";
import { renderNotices } from "./sbom.ts";

const mplHeader = [
  "// Generated by a script. Don't edit by hand.",
  "//",
  "// This Source Code Form is subject to the terms of the Mozilla Public",
  "// License, v. 2.0. If a copy of the MPL was not distributed with this",
  "// file, You can obtain one at https://mozilla.org/MPL/2.0/.",
  "",
  "export const rules = `com`;",
].join("\n");

const psl = "packages/core/std/src/psl.ts";
const mplText = "tooling/check/licence-texts/MPL-2.0.txt";

const entry = {
  path: psl,
  name: "Public Suffix List",
  licence: "MPL-2.0",
  source: "https://publicsuffix.org/list/public_suffix_list.dat",
  task: "HAL-6165",
};

const policy = (vendored: NonNullable<LicencePolicy["vendored"]>): LicencePolicy => ({
  shipped: ["MIT"],
  devOnly: ["MPL-2.0"],
  corrections: {},
  vendored,
});

/** Runs the check over a repo made of `files`, path → text. */
function problems(
  files: Record<string, string>,
  vendored: NonNullable<LicencePolicy["vendored"]>,
): string[] {
  return findVendoredProblems(Object.keys(files), (path) => files[path] ?? "", policy(vendored));
}

verifies("check.licences-vendored", () => {
  test("fails on an unlisted file with an MPL header and passes once it is listed", () => {
    const unlisted = problems({ [psl]: mplHeader, [mplText]: "MPL" }, []);
    expect(unlisted).toHaveLength(1);
    expect(unlisted[0]).toContain(psl);
    expect(unlisted[0]).toContain("Mozilla Public License");
    expect(problems({ [psl]: mplHeader, [mplText]: "MPL" }, [entry])).toEqual([]);
  });

  test("fails when an entry's file is gone or its licence text is missing", () => {
    const gone = problems({ [mplText]: "MPL" }, [entry]);
    expect(gone).toHaveLength(1);
    expect(gone[0]).toContain("is gone");
    const noText = problems({ [psl]: mplHeader }, [entry]);
    expect(noText).toHaveLength(1);
    expect(noText[0]).toContain(mplText);
  });

  test("fails on an entry without a source or task", () => {
    const { source: _source, task: _task, ...partial } = entry;
    const found = problems({ [psl]: mplHeader, [mplText]: "MPL" }, [
      partial as unknown as typeof entry,
    ]);
    expect(found).toHaveLength(1);
    expect(found[0]).toContain("needs source, task");
  });

  test("reads @license tags, GNU licences and SPDX tags other than ours", () => {
    expect(thirdPartyLicenceMark("/*! @license lib v1 | (c) Someone */\nvar a;")).toBe(
      "an @license tag",
    );
    expect(
      thirdPartyLicenceMark(
        "# This program is free software under the GNU General\n# Public License.\n",
      ),
    ).toBe("a GNU General Public License");
    expect(thirdPartyLicenceMark("/* SPDX-License-Identifier: MIT */\n")).toBe(
      'the SPDX tag "MIT"',
    );
    expect(thirdPartyLicenceMark("#!/bin/sh\n#\n# SPDX-License-Identifier: Apache-2.0\n")).toBe(
      undefined,
    );
    expect(thirdPartyLicenceMark("export const a = 1;\n")).toBe(undefined);
    expect(
      thirdPartyLicenceMark("// The licence comment holds `@license`, so bundlers keep it.\n"),
    ).toBe(undefined);
  });

  test("only reads the comment block at the top, and only under packages/ and apps/", () => {
    const script = [
      "// Writes our copy of the list.",
      "const header = `// This Source Code Form is subject to the terms of the Mozilla Public",
      "// License, v. 2.0.`;",
    ].join("\n");
    expect(leadingComments(script)).toBe("// Writes our copy of the list.");
    expect(
      problems(
        {
          "packages/core/std/scripts/refresh.ts": script,
          "tooling/check/src/fixture.ts": mplHeader,
          "apps/studio/src/main.ts": "/**\n * @license MPL-2.0\n */\nexport {};",
        },
        [],
      ),
    ).toEqual([expect.stringContaining("apps/studio/src/main.ts")]);
  });

  test("the notices end with one block per vendored file, with its source and text", () => {
    const text = renderNotices(
      "Halonic",
      [{ name: "zod", versions: ["4.0.0"], licence: "MIT", text: "MIT text" }],
      [{ ...entry, text: "Mozilla Public License Version 2.0\n" }],
    );
    const block = text.slice(text.indexOf("Public Suffix List ("));
    expect(text.indexOf("zod 4.0.0")).toBeLessThan(text.indexOf("Public Suffix List ("));
    expect(block).toContain(`Public Suffix List (${psl})`);
    expect(block).toContain("Licence: MPL-2.0");
    expect(block).toContain(`Source: ${entry.source}`);
    expect(block).toContain("Mozilla Public License Version 2.0");
  });
});
